WITH daily_agg AS ( SELECT cr.cr_returned_date_sk AS return_date, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_return_quantity) AS total_return_qty, cp.cp_department, r.r_reason_desc, SUM(CASE WHEN cd.cd_gender = 'M' THEN 1 ELSE 0 END) AS male_cnt, COUNT(*) AS total_cnt FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk JOIN customer_demographics cd ON cr.cr_returning_cdemo_sk = cd.cd_demo_sk GROUP BY cr.cr_returned_date_sk, cp.cp_department, r.r_reason_desc HAVING SUM(cr.cr_return_amount) > 5000 ) SELECT return_date, total_return_amount, total_return_qty, cp_department, r_reason_desc, male_cnt, total_cnt, CAST(male_cnt AS double) / total_cnt AS male_ratio, ROW_NUMBER() OVER (ORDER BY total_return_amount ASC) AS amount_rank_asc, AVG(total_return_amount) OVER (PARTITION BY r_reason_desc ORDER BY return_date ROWS BETWEEN 7 PRECEDING AND CURRENT ROW) AS moving_avg_7d FROM daily_agg ORDER BY amount_rank_asc LIMIT 25
